        key.preventDefault();
        if (rows > 0)
            act.select((selected) => (selected + step + rows) % rows);
    };
    if (key.name === "escape")
        return act.close();
    // Typing that arrives before the dialog's input mounts would reach the still-focused composer.
    const typed = typing(key);
    if (state.composerFocused && open.kind !== "stop" && typed !== undefined) {
        key.preventDefault();
        return act.type(typed);
    }
    if (key.name === "up" || (key.ctrl && key.name === "p"))
        return move(-1);
    if (key.name === "down" || (key.ctrl && key.name === "n"))
        return move(1);
    if (key.name === "pageup")
        return move(-Math.min(10, open.selected));
    if (key.name === "pagedown")
        return move(Math.min(10, rows - 1 - open.selected));
