        key.preventDefault();
        if (count > 0)
            act.select((index) => (index + step + count) % count);
        return true;
    };
    if (key.name === "up" || (key.ctrl && key.name === "p"))
        return move(-1);
    if (key.name === "down" || (key.ctrl && key.name === "n"))
        return move(1);
    if (key.name === "escape") {
        key.preventDefault();
        act.dismiss();
        return true;
    }
    if (count === 0)
        return false;
    if (key.name === "tab" && !key.shift) {
        key.preventDefault();
        act.accept(false);
        return true;
    }
    if ((key.name === "return" || key.name === "kpenter") && !key.shift && !key.meta && !key.option) {
        key.preventDefault();
        act.accept(true);
