        return act.release();
    key.preventDefault();
    if (key.name === "escape")
        return act.close();
    if (key.name === "i")
        return act.release();
    if (key.name === "r" && surface.startsWith("flow:") && state.flow.retry)
        return act.retryRun(surface.slice(5));
    if (key.name === "c" && surface.startsWith("flow:") && state.flow.continue)
        return act.continueRun(surface.slice(5));
    if (key.name === "x" && surface.startsWith("flow:") && state.flow.stop)
        return act.cancelRun(surface.slice(5));
    if (key.name === "a" && surface.startsWith("flow:"))
        return act.fillRun(surface.slice(5));
    if (key.name === "u" && surface === "summary") {
        return act.undo(panel.rows[Math.min(navigation.selected, panel.rows.length - 1)]);
    }
